import React, { useContext, useEffect, useState } from 'react';
import { Modal, Button, Form, Row, Col, Alert } from 'react-bootstrap';
import { FaBookOpen, FaBuilding, FaCalendarAlt, FaImage } from 'react-icons/fa';
import { AuthContext } from '../../App';
import {
  fetchClassSubjects,
  uploadHomeworkImage,
  createHomeworkUpload,
} from '../../services/HomeworkServices/homeworkServices';

function HomeworkModal(props) {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const [subjects, setSubjects] = useState([]);
  const [subjectId, setSubjectId] = useState('');
  const [description, setDescription] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [uploading, setUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [alertShow, setAlertShow] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [alertVarient, setAlertVarient] = useState('');

  const instituteName = user.instnm || '';
  const branchName = user.brcnm || '';
  const academicYear = user.acdmcyr || '';
  const className = user.clsnm || '';
  const sectionName = user.secnm || '';
  const classId = user.clsid || '';
  const sectionId = user.secid || '';
  const staffId = user.stfid || '';

  useEffect(() => {
    if (props.show && classId) {
      loadSubjects();
    }
  }, [props.show, classId]);

  useEffect(() => {
    if (!props.show) {
      setSubjectId('');
      setDescription('');
      setImageUrl('');
      setAlertShow(false);
    }
  }, [props.show]);

  const loadSubjects = async () => {
    const res = await fetchClassSubjects({ clsid: classId });
    if (res && res.status === 'success' && res.payload) {
      setSubjects(res.payload || []);
    } else {
      setSubjects([]);
    }
  };

  const hideMessage = () => {
    setTimeout(() => {
      setAlertShow(false);
      setAlertMessage('');
      setAlertVarient('');
    }, 5000);
  };

  const handleImageChange = async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setUploading(true);
    const newFile = new File([file], file.name, {
      type: file.type,
      lastModified: file.lastModified,
    });
    const formData = new FormData();
    formData.append('image', newFile);
    formData.append('type', 'homework');
    formData.append('imgtyp', 'student_photo');
    const res = await uploadHomeworkImage(formData);
    setUploading(false);
    if (res && res.status === 'success' && res.payload && res.payload.url) {
      setImageUrl(res.payload.url);
      setAlertMessage('Image Uploaded Successfully');
      setAlertVarient('success');
      setAlertShow(true);
      hideMessage();
    } else {
      setAlertMessage('Failed to Upload the Image');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
    }
  };

  const handleSubmit = async () => {
    if (!description) {
      setAlertMessage('Please Enter Description');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
      return;
    }
    setIsSaving(true);
    const payload = {
      fkinstid: user.instid,
      fkbrcid: user.brcid,
      desc: description,
      fkclsid: classId,
      fksubid: subjectId,
      fksecid: sectionId,
      stfid: staffId,
      imguld: imageUrl,
      acdmcyr: academicYear,
      usrid: user.usrid,
    };
    const res = await createHomeworkUpload(payload);
    setIsSaving(false);
    if (res && res.status === 'success') {
      setAlertMessage('Home Work Upload Created Successfully');
      setAlertVarient('success');
      setAlertShow(true);
      hideMessage();
      props.onClose();
    } else {
      setAlertMessage(res?.error?.message || 'Failed to Upload Home Work');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
    }
  };

  return (
    <Modal show={props.show} onHide={props.onClose} size="lg" centered>
      <Modal.Header closeButton>
        <Modal.Title className="d-flex align-items-center gap-2">
          <FaBookOpen className="text-primary" />
          Home Work Upload
        </Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <Alert
          variant={alertVarient}
          show={alertShow}
          onClose={() => setAlertShow(false)}
          dismissible
        >
          {alertMessage}
        </Alert>

        {/* Institute + Branch default from login response */}
        <div className="hw-default-card">
          <Row>
            <Col md={6}>
              <div className="hw-default-item">
                <FaBuilding className="hw-default-icon" />
                <div>
                  <span>Institute</span>
                  <strong>{instituteName || '—'}</strong>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <div className="hw-default-item">
                <FaBuilding className="hw-default-icon" />
                <div>
                  <span>Branch</span>
                  <strong>{branchName || '—'}</strong>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <div className="hw-default-item">
                <FaCalendarAlt className="hw-default-icon" />
                <div>
                  <span>Academic Year</span>
                  <strong>{academicYear || '—'}</strong>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <div className="hw-default-item">
                <FaBookOpen className="hw-default-icon" />
                <div>
                  <span>Class / Section</span>
                  <strong>
                    {className || '—'} {sectionName ? `- ${sectionName}` : ''}
                  </strong>
                </div>
              </div>
            </Col>
          </Row>
        </div>

        <Form className="mt-3">
          <Form.Group className="mb-3">
            <Form.Label>Subject</Form.Label>
            <Form.Select
              value={subjectId}
              onChange={(e) => setSubjectId(e.target.value)}
            >
              <option value="">Select Subject</option>
              {subjects.map((s) => (
                <option key={s.subid} value={s.subid}>
                  {s.subnm}
                </option>
              ))}
            </Form.Select>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Description</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              placeholder="Enter home work description..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </Form.Group>

          <Form.Group className="mb-2">
            <Form.Label>
              <FaImage className="me-1" /> Image Upload
            </Form.Label>
            <Form.Control
              type="file"
              accept=".png,.jpg,.jpeg,.bmp,.pdf"
              onChange={handleImageChange}
            />
            <Form.Text className="text-muted">
              {uploading ? 'Uploading The Image...' : ''}
            </Form.Text>
          </Form.Group>

          {imageUrl && (
            <div className="hw-image-preview">
              {imageUrl.toLowerCase().endsWith('.pdf') ? (
                <a href={imageUrl} target="_blank" rel="noreferrer">
                  View PDF
                </a>
              ) : (
                <img src={imageUrl} alt="homework" width="120" />
              )}
            </div>
          )}
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="secondary" onClick={props.onClose}>
          Cancel
        </Button>
        <Button variant="primary" onClick={handleSubmit} disabled={isSaving || uploading}>
          {isSaving ? 'Uploading...' : 'Submit'}
        </Button>
      </Modal.Footer>
    </Modal>
  );
}

export default HomeworkModal;
